INSERT INTO setting_template_refs(tenant_id,id,subject,kind,template_key,entity_id) SELECT t.tenant_id,'tref_'||lower(hex(randomblob(12))),'music_interest','stage_types','s_3891a48f77e1',t.id FROM stage_types t JOIN tenant_subjects s ON s.tenant_id=t.tenant_id AND s.id=t.subject WHERE t.subject='music_interest' AND t.source='template' AND t.version=1 AND t.name='体验与适应' AND s.pack_version='0.1';
